 await test('14_cross_tenant_and_unassigned_branch_denied',async()=>{assert((await http(stockPath(b,t2))).status===403,'Cross-tenant read permitted');assert((await http(adjustPath(b,t2),'POST',adjust(1))).status===403,'Cross-tenant adjustment permitted');assert((await http(stockPath(b2))).status===403,'Unassigned read permitted');assert((await http(adjustPath(b2),'POST',adjust(1))).status===403,'Unassigned adjustment permitted');});
 await test('15_initial_stock_zero',async()=>{const q=await http(stockPath());assert(q.status===200&&q.cache==='no-store'&&q.data.quantity==='0','Initial stock invalid');});
 await test('16_client_stock_fields_and_invalid_deltas_rejected',async()=>{for(const change of [{quantityDelta:0},{quantityDelta:1.5},{quantityDelta:'1'},{balanceAfter:'9'},{tenantId:t},{branchId:b},{reason:'\t\t'},{requestId:'bad'}])assert((await http(adjustPath(),'POST',{...adjust(1),...change})).status===400,'Invalid adjustment accepted');assert((await http(stockPath()+'?day=2026-10-15')).status===400,'Unknown stock query accepted');});
 const movementBody=adjust(10);let movement;
 await test('17_stock_adjustment_and_retry',async()=>{const q=await http(adjustPath(),'POST',movementBody);assert(q.status===200&&q.data.balanceAfter==='10'&&q.data.quantityDelta===10,'Stock adjustment failed');movement=q.data;const retry=await http(adjustPath(),'POST',movementBody);assert(retry.status===200&&JSON.stringify(retry.data)===JSON.stringify(movement),'Stock retry mismatch');});
