 await test('19_concurrent_withdrawals_prevent_overselling',async()=>{const q=await Promise.all([http(adjustPath(),'POST',adjust(-7)),http(adjustPath(),'POST',adjust(-7))]);assert(q.filter(x=>x.status===200).length===1&&q.filter(x=>x.status===400).length===1,'Withdrawals not serialized');assert((await http(stockPath())).data.quantity==='3','Concurrent withdrawal balance mismatch');});
