 await test('22_audit_counts_and_other_branch_unchanged',async()=>{const q=(await db.query('SELECT quantity_delta,actor_membership_id,actor_snapshot,product_snapshot FROM app.inventory_stock_movements WHERE tenant_id=$1 AND product_id=$2',[t,product])).rows;assert(q.length===3&&q.reduce((a,x)=>a+x.quantity_delta,0)===8&&q.every(x=>x.actor_membership_id===m&&x.actor_snapshot.userId===u&&x.product_snapshot.salePrice==='2000.00'),'Audit or movement count mismatch');assert((await db.query('SELECT count(*)::int AS n FROM app.inventory_stock_movements WHERE tenant_id=$1 AND branch_id=$2',[t,b2])).rows[0].n===0,'Other branch stock changed');});

 const sales=(branch=b,tenant=t)=>`/tenants/${tenant}/branches/${branch}/pos/sales`;
 const sell=(items,requestId=randomUUID())=>http(sales(),'POST',{items,requestId});
 const basket=[{productId:product,quantity:2},{productId:product2,quantity:3}];
 async function ledger(){return (await db.query("SELECT jsonb_build_object('sales',(SELECT count(*) FROM app.pos_sales WHERE tenant_id=$1 AND branch_id=$2),'items',(SELECT count(*) FROM app.pos_sale_items WHERE tenant_id=$1 AND branch_id=$2),'movements',(SELECT count(*) FROM app.inventory_stock_movements WHERE tenant_id=$1 AND branch_id=$2),'stock',(SELECT jsonb_object_agg(product_id,q) FROM (SELECT product_id,sum(quantity_delta)::text q FROM app.inventory_stock_movements WHERE tenant_id=$1 AND branch_id=$2 GROUP BY product_id) x)) AS v",[t,b])).rows[0].v;}
 async function runtime(sql,args){await db.query('BEGIN');try{await db.query('SET LOCAL ROLE gympro_app');const q=await db.query(sql,args);await db.query('COMMIT');return q;}catch(e){await db.query('ROLLBACK');throw e;}}
 async function sqlDenied(fn,state){let code;try{await fn();}catch(e){code=e.code;}assert(code===state,`Expected SQLSTATE ${state}, received ${code??'success'}`);}
 await test('D4_01_unauthenticated_sale_routes',async()=>{assert((await http(sales(),'POST',{items:basket,requestId:randomUUID()},null)).status===401,'Unauthenticated sale allowed');assert((await http(sales()+'/'+randomUUID(),'GET',undefined,null)).status===401,'Unauthenticated receipt allowed');});
