  await db.query('BEGIN');try{await db.query('SET LOCAL ROLE gympro_app');const probe=await db.query('SELECT security.create_pos_sale($1,$2,$3,$4,$5) AS receipt',[sqlHash,t,b,JSON.stringify(basket),saleBody.requestId]);assert(probe.rows[0].receipt.totalAmount==='7000.00','Direct SQL sale total mismatch');}finally{await db.query('ROLLBACK');}
