 await test('D4_08_dedicated_read_permission_and_receipt',async()=>{await db.query("INSERT INTO app.role_permissions(tenant_id,role_id,permission_id) SELECT $1,$2,id FROM app.permissions WHERE permission_code='pos.sales.read' AND is_active",[t,r2]);const q=await http(sales()+'/'+saleReceipt.id);assert(q.status===200&&q.cache==='no-store'&&JSON.stringify(q.data)===JSON.stringify(saleReceipt),'Receipt lookup mismatch');});
