 await test('D4_14_sale_stock_movement_cannot_be_reused_as_adjustment',async()=>{const line=saleReceipt.items.find(i=>i.productId===product);const q=await http(adjustPath(),'POST',adjust(-line.quantity,line.id,'POS sale'));assert(q.status===400,'Sale movement relabeled as adjustment');});
 await test('D4_15_concurrent_sales_prevent_overselling',async()=>{const before=await ledger();const q=await Promise.all([sell([{productId:product,quantity:12}]),sell([{productId:product,quantity:12}])]);assert(q.filter(x=>x.status===201).length===1&&q.filter(x=>x.status===400).length===1,'Concurrent sales oversold');const after=await ledger();assert(after.stock[product]==='6'&&after.sales===before.sales+1,'Concurrent sales balance/count wrong');});
