 await test('D9_03_default_Yangon_dates_and_public_fields',async()=>{const day=(await db.query("SELECT (clock_timestamp() AT TIME ZONE 'Asia/Yangon')::date::text AS day")).rows[0].day,from=new Date(Date.parse(day+'T00:00:00Z')-29*86400000).toISOString().slice(0,10);const q=await http(movements()+'?limit=100');assert(q.status===200&&q.cache==='no-store'&&q.data.tenantId===t&&q.data.branchId===b&&q.data.productId===product&&q.data.from===from&&q.data.through===day,'Stock history default range/scope invalid');assert(q.data.items.length>0&&q.data.items.every(i=>i.productId===product&&typeof i.balanceAfter==='string'&&!('actorSnapshot'in i)&&!('productSnapshot'in i)&&!('userId'in i)&&!('sessionId'in i)&&!('requestId'in i)),'Private stock history fields exposed');});
 await test('D9_04_movement_balances_reasons_snapshots_and_staff',async()=>{const q=await http(movements()+'?limit=100');const expected=(await db.query("SELECT mv.id,mv.quantity_delta,mv.balance_after::text,mv.reason,mv.movement_kind,mv.product_snapshot->>'productName' AS product_name,mv.product_snapshot->>'sku' AS sku,mv.actor_membership_id,u.full_name FROM app.inventory_stock_movements mv JOIN app.tenant_memberships tm ON tm.tenant_id=mv.tenant_id AND tm.id=mv.actor_membership_id JOIN app.users u ON u.id=tm.user_id WHERE mv.tenant_id=$1 AND mv.branch_id=$2 AND mv.product_id=$3 ORDER BY mv.created_at DESC,mv.id DESC",[t,b,product])).rows;assert(q.status===200&&q.data.items.length===expected.length,'Movement count mismatch');for(let n=0;n<expected.length;n++){const a=q.data.items[n],e=expected[n];assert(a.id===e.id&&a.quantityDelta===e.quantity_delta&&a.balanceAfter===e.balance_after&&a.reason===e.reason&&a.kind===e.movement_kind&&a.productName===e.product_name&&a.sku===e.sku&&a.actorMembershipId===m&&a.actorName===e.full_name,'Movement snapshot/staff mismatch');}});
 await test('D9_05_keyset_pages_have_no_duplicates_or_gaps',async()=>{const all=await http(movements()+'?limit=100'),ids=[];let cursor=null;for(let n=0;n<500;n++){const q=await http(movements()+'?limit=1'+(cursor?'&cursor='+cursor:''));assert(q.status===200&&q.data.items.length<=1,'Movement page failed');ids.push(...q.data.items.map(i=>i.id));cursor=q.data.nextCursor;if(!cursor)break;}assert(JSON.stringify(ids)===JSON.stringify(all.data.items.map(i=>i.id))&&new Set(ids).size===ids.length,'Movement pagination duplicated/skipped rows');});
 await test('D9_06_all_four_movement_types_and_inactive_products',async()=>{const q=await http(movements()+'?limit=100');assert(['adjustment','sale','refund','void'].every(kind=>q.data.items.some(i=>i.kind===kind)),'Movement kinds missing');assert(q.data.items.every(i=>i.kind!=='sale'||i.quantityDelta<0)&&q.data.items.every(i=>!['refund','void'].includes(i.kind)||i.quantityDelta>0),'Movement signs wrong');const inactive=await http(movements(product2)+'?limit=100');assert(inactive.status===200&&inactive.data.items.some(i=>i.kind==='refund'),'Inactive product history denied');});
 await test('D9_07_scope_and_product_cursor_isolation',async()=>{assert((await http(movements(product,b2))).status===403,'Other branch history allowed');assert((await http(movements(product,b,t2))).status===403,'Cross-tenant history allowed');assert((await http(movements(randomUUID()))).status===400,'Unknown product accepted');const other=(await db.query('SELECT id FROM app.inventory_stock_movements WHERE tenant_id=$1 AND branch_id=$2 AND product_id=$3 LIMIT 1',[t,b,product2])).rows[0].id;assert((await http(movements()+'?cursor='+other)).status===400,'Other product cursor accepted');assert((await http(movements()+'?cursor='+randomUUID())).status===400,'Unknown movement cursor accepted');});
 await test('D9_08_invalid_history_queries_rejected',async()=>{for(const query of ['?from=2026-01-01','?through=2026-01-01','?from=2026-02-30&through=2026-03-01','?from=2026-10-15&through=2026-10-14','?from=2025-01-01&through=2026-01-02','?limit=0','?limit=101','?limit=1.5','?cursor=bad','?actorMembershipId='+m,'?from=2026-01-01&from=2026-01-02&through=2026-01-03'])assert((await http(movements()+query)).status===400,'Invalid movement query accepted: '+query);});
 await test('D9_09_direct_SQL_permissions_and_read_only_owner',async()=>{const hash=(await db.query('SELECT session_token_hash FROM security.tenant_sessions WHERE tenant_id=$1 AND membership_id=$2 AND revoked_at IS NULL',[t,m])).rows[0].session_token_hash,sql='SELECT security.read_inventory_stock_history($1,$2,$3,$4,$5,$6,$7,$8)';await sqlDenied(()=>runtime(sql,[randomBytes(32),t,b,product,null,null,null,25]),'28000');await sqlDenied(()=>runtime(sql,[hash,t,b2,product,null,null,null,25]),'42501');await sqlDenied(()=>runtime(sql,[hash,t2,b,product,null,null,null,25]),'42501');await sqlDenied(()=>runtime(sql,[hash,t,b,product,'infinity','infinity',null,25]),'22023');await sqlDenied(()=>runtime(sql,[hash,t,b,product,null,null,null,101]),'22023');const safe=(await db.query("SELECT NOT has_table_privilege('gympro_inventory_read_owner','app.inventory_stock_movements','INSERT,UPDATE,DELETE') AND NOT has_column_privilege('gympro_inventory_read_owner','app.users','password_hash','SELECT') AND NOT has_table_privilege('gympro_app','app.inventory_stock_movements','SELECT,INSERT,UPDATE,DELETE') AND (SELECT NOT rolcanlogin AND NOT rolinherit AND NOT rolsuper AND NOT rolbypassrls FROM pg_roles WHERE rolname='gympro_inventory_read_owner') AS safe")).rows[0].safe;assert(safe,'History role has unsafe privileges');await sqlDenied(async()=>{await db.query('BEGIN');try{await db.query('SET LOCAL ROLE gympro_inventory_read_owner');await db.query('SELECT password_hash FROM app.users LIMIT 1');}finally{await db.query('ROLLBACK');}},'42501');});
 await test('D9_10_Yangon_boundary_and_equal_timestamp_pagination',async()=>{const rows=(await db.query('SELECT id,created_at::text AS original FROM app.inventory_stock_movements WHERE tenant_id=$1 AND branch_id=$2 AND product_id=$3 ORDER BY created_at,id LIMIT 5',[t,b,product])).rows;assert(rows.length===5,'Expected five movement fixtures');const today=(await db.query("SELECT (clock_timestamp() AT TIME ZONE 'Asia/Yangon')::date::text AS day")).rows[0].day,day=new Date(Date.parse(today+'T00:00:00Z')-10*86400000).toISOString().slice(0,10),start=Date.parse(day+'T00:00:00Z')-23400000,end=start+86400000,last=new Date(end-1).toISOString().replace('.999Z','.999999Z'),dates=[new Date(start-1).toISOString(),new Date(start).toISOString(),last,last,new Date(end).toISOString()];try{for(let n=0;n<5;n++)await db.query('UPDATE app.inventory_stock_movements SET created_at=$2::timestamptz WHERE id=$1',[rows[n].id,dates[n]]);const expected=[rows[2].id,rows[3].id].sort().reverse().concat(rows[1].id),all=await http(movements()+`?from=${day}&through=${day}&limit=100`);assert(all.status===200&&JSON.stringify(all.data.items.map(i=>i.id))===JSON.stringify(expected),'Movement day boundaries wrong');const ids=[];let cursor=null;for(let n=0;n<5;n++){const q=await http(movements()+`?from=${day}&through=${day}&limit=1`+(cursor?'&cursor='+cursor:''));assert(q.status===200,'Equal timestamp page failed');ids.push(...q.data.items.map(i=>i.id));cursor=q.data.nextCursor;if(!cursor)break;}assert(JSON.stringify(ids)===JSON.stringify(expected),'Equal timestamp movements duplicated/skipped');assert((await http(movements()+`?from=${day}&through=${day}&cursor=${rows[0].id}`)).status===400,'Outside-range cursor accepted');}finally{for(const row of rows)await db.query('UPDATE app.inventory_stock_movements SET created_at=$2::timestamptz WHERE id=$1',[row.id,row.original]);}});
 await test('D9_11_empty_range_and_reads_change_nothing',async()=>{const fingerprint=async()=>JSON.stringify((await db.query("SELECT jsonb_agg(to_jsonb(mv) ORDER BY mv.id) AS v FROM app.inventory_stock_movements mv WHERE mv.tenant_id=$1 AND mv.branch_id=$2",[t,b])).rows[0].v);const before=await fingerprint();for(let n=0;n<3;n++)assert((await http(movements()+'?limit=100')).status===200,'Repeated history failed');const empty=await http(movements()+'?from=2000-01-01&through=2000-01-01');assert(empty.status===200&&empty.data.items.length===0&&empty.data.nextCursor===null,'Empty movement range invalid');assert(await fingerprint()===before,'History reads changed ledger data');});

 await test('23_inactive_branch_denied',async()=>{await db.query("UPDATE app.branches SET status='inactive' WHERE id=$1",[b]);try{assert((await http(stockPath())).status===403,'Inactive branch read permitted');assert((await http(adjustPath(),'POST',movementBody)).status===403,'Inactive branch retry permitted');assert((await http(sales(),'POST',saleBody)).status===403,'Inactive branch sale retry permitted');assert((await refund(partialBody)).status===403,'Inactive branch refund retry permitted');assert((await voidSale(voidBody,voidedSale.id)).status===403,'Inactive branch void retry permitted');assert((await returnState()).status===403,'Inactive branch return state permitted');assert((await http(sales())).status===403,'Inactive branch history allowed');assert((await http(movements())).status===403,'Inactive branch stock history allowed');}finally{await db.query("UPDATE app.branches SET status='active' WHERE id=$1",[b]);}});
